const AGENTS_CACHE_TTL = 30000;
export default async ({ client }) => {
  let agentsCache = null;
  let agentsCacheTime = 0;
  async function loadAgents() {
    const now = Date.now();
    if (agentsCache && now - agentsCacheTime < AGENTS_CACHE_TTL) {
      return agentsCache;
    }
    try {
      const agents = await client.app.agents();
      agentsCache = agents;
      agentsCacheTime = now;
      return agents;
    } catch (e) {
      client.app.log({
        body: { service: "phase0-guard", level: "error", message: `agents API: ${e}` }
      });
      return agentsCache || [];
    }
  }
  let agents = await loadAgents();
  const timer = setInterval(async () => {
    agents = await loadAgents();
  }, AGENTS_CACHE_TTL);
  return {
    config: (cfg) => {
      if (!agents || agents.length === 0)
        return;
      const agentConfigs = cfg.agent;
      if (!agentConfigs)
        return;
      for (const [agentName, agentCfg] of Object.entries(agentConfigs)) {
        const apiAgent = agents.find((a) => a.name === agentName);
        if (!apiAgent)
          continue;
        const denyNames = new Set;
        if (apiAgent.permission) {
          for (const [key, rule] of Object.entries(apiAgent.permission)) {
            if (rule === "deny")
              denyNames.add(key);
            else if (typeof rule === "object" && rule !== null) {
              for (const [pat, action] of Object.entries(rule)) {
                if (action === "deny")
                  denyNames.add(pat);
              }
            }
          }
        }
        if (apiAgent.tools) {
          for (const [key, val] of Object.entries(apiAgent.tools)) {
            if (val === false)
              denyNames.add(key);
          }
        }
        if (denyNames.size === 0)
          continue;
        const currentTools = agentCfg.tools || {};
        let modified = false;
        for (const name of denyNames) {
          if (currentTools[name] !== false) {
            currentTools[name] = false;
            modified = true;
          }
        }
        if (modified) {
          agentCfg.tools = currentTools;
        }
      }
    },
    dispose: () => {
      clearInterval(timer);
    }
  };
};

